INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (24, 'Jahitan safety stitch tidak terbentuk dengan benar', 'Jahitan kombinasi overlock dan chainstitch tidak terbentuk rapi atau sebagian jahitan tidak terkunci.', 'Ketegangan lima benang tidak seimbang, jalur threading tidak benar, atau penyetelan jarum dan looper tidak tepat.', 'Periksa seluruh jalur lima benang, seimbangkan tegangan, dan periksa posisi jarum serta looper.', 'Matikan mesin dan lepaskan pedal sebelum melakukan pemeriksaan atau penyetelan.', 'Data spesifikasi JUKI MO-6816S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (24, 'Benang salah satu jarum sering putus', 'Benang pada salah satu jarum putus berulang saat mesin menjahit.', 'Jarum bengkok atau tumpul, pemasangan jarum tidak tepat, tegangan terlalu tinggi, atau jalur benang bermasalah.', 'Ganti jarum DC×27 yang sesuai, pastikan kedua jarum terpasang benar, periksa jalur benang dan sesuaikan tegangan.', 'Matikan mesin sebelum mengganti jarum atau menyentuh area jarum.', 'Data spesifikasi JUKI MO-6816S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (24, 'Benang looper atau chain looper sering putus', 'Salah satu benang looper atau chainstitch putus sehingga struktur safety stitch tidak lengkap.', 'Jalur threading looper tidak benar, tegangan terlalu tinggi, atau looper mengalami gangguan.', 'Periksa jalur threading, sesuaikan tegangan secara bertahap, dan periksa gerakan looper dari kemungkinan tersangkut.', 'Matikan mesin dan pastikan semua bagian bergerak berhenti sebelum memeriksa looper.', 'Data spesifikasi JUKI MO-6816S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (24, 'Jahitan chainstitch loncat atau tidak terbentuk', 'Bagian chainstitch pada safety stitch tidak terbentuk secara konsisten.', 'Jarum salah pasang atau bengkok, timing jarum dan looper tidak tepat, atau threading salah.', 'Periksa pemasangan kedua jarum, ganti jarum yang rusak, periksa threading, dan lakukan pemeriksaan timing jika diperlukan.', 'Pemeriksaan timing dilakukan hanya saat mesin mati dan aman dari kemungkinan bergerak.', 'Data spesifikasi JUKI MO-6816S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (24, 'Tepi kain mengerut atau bergelombang', 'Tepi kain tertarik, mengerut, atau bergelombang setelah dijahit.', 'Differential feed tidak sesuai dengan karakteristik material atau tekanan sepatu penekan tidak sesuai.', 'Sesuaikan differential feed secara bertahap dan periksa tekanan sepatu penekan sesuai jenis material.', 'Lakukan penyetelan saat mesin berhenti dan hindari menyentuh area jarum ketika mesin berjalan.', 'Data spesifikasi JUKI MO-6816S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (24, 'Lebar obras atau posisi jahitan tidak sesuai', 'Lebar overedge atau posisi jahitan safety stitch tidak sesuai dengan hasil yang diharapkan.', 'Penyetelan overedge width tidak sesuai atau posisi komponen pembentuk jahitan dan pemotong perlu diperiksa.', 'Periksa penyetelan lebar obras dan pastikan komponen pembentuk jahitan serta pemotong berada pada posisi yang benar.', 'Matikan mesin sebelum melakukan penyetelan di sekitar pisau atau mekanisme jahitan.', 'Data spesifikasi JUKI MO-6816S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (24, 'Jarum patah atau posisi jarum tidak normal', 'Salah satu atau kedua jarum patah, menyentuh komponen lain, atau bergerak tidak normal.', 'Jarum salah ukuran atau bengkok, pemasangan tidak benar, atau terdapat gangguan pada mekanisme jarum dan looper.', 'Ganti jarum DC×27 yang sesuai, pastikan kedua jarum terpasang benar, lalu periksa jarak jarum terhadap looper dan komponen sekitarnya.', 'Jangan mengganti atau memeriksa jarum ketika mesin masih terhubung dan dapat beroperasi.', 'Data spesifikasi JUKI MO-6816S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (24, 'Pelumasan atau gerakan mesin tidak normal', 'Mesin terasa berat, mengeluarkan suara tidak normal, atau gerakannya tidak lancar saat menjahit.', 'Sistem pelumasan tidak bekerja optimal, terdapat kotoran pada mekanisme, atau komponen bergerak mengalami masalah.', 'Periksa sistem pelumasan otomatis, bersihkan area yang dapat diakses, dan hentikan mesin untuk pemeriksaan lebih lanjut jika suara atau gerakan tetap tidak normal.', 'Matikan mesin sebelum membersihkan atau memeriksa bagian bergerak. Jangan menyentuh mekanisme yang sedang berputar.', 'Data spesifikasi JUKI MO-6816S dan panduan pemeriksaan umum');
